                    <h2 id="admin-users-sessions-PATCHapi-users--user_id-">Modifier un utilisateur</h2>

<p>
</p>

<p>Met à jour les informations de base de l'utilisateur.</p>

<span id="example-requests-PATCHapi-users--user_id-">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request PATCH \
    "http://localhost:8000/api/users/1" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"display_name\": \"architecto\",
    \"handle\": \"architecto\",
    \"birth_date\": \"2026-10-08T16:12:12\",
    \"gender\": \"architecto\",
    \"locale\": \"sr_BA\",
    \"account_type\": \"architecto\",
    \"status\": \"architecto\",
    \"is_verified\": false
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/users/1"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "display_name": "architecto",
    "handle": "architecto",
    "birth_date": "2026-10-08T16:12:12",
    "gender": "architecto",
    "locale": "sr_BA",
    "account_type": "architecto",
    "status": "architecto",
    "is_verified": false
};

fetch(url, {
    method: "PATCH",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

</span>

